import csv
import io
import re
import collections
import typing


def _split_logical_records(text: str) -> typing.List[str]:
    records = []
    start = 0
    quoted = False
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == '"':
            if quoted:
                if i + 1 < len(text) and text[i + 1] == '"':
                    i += 1
                else:
                    quoted = False
            else:
                quoted = True
        elif ch == "\n" and not quoted:
            record = text[start:i]
            if record.endswith("\r"):
                record = record[:-1]
            records.append(record)
            start = i + 1
        i += 1
    if start < len(text) or text.endswith(("\n", "\r")):
        record = text[start:]
        if record.endswith("\r"):
            record = record[:-1]
        records.append(record)
    return records


def _has_unquoted_comma(text: str) -> bool:
    quoted = False
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == '"':
            if quoted:
                if i + 1 < len(text) and text[i + 1] == '"':
                    i += 1
                else:
                    quoted = False
            else:
                quoted = True
        elif ch == "," and not quoted:
            return True
        i += 1
    return False


def _parse_space_record(text: str) -> typing.List[str]:
    values = []
    current = []
    quoted = False
    i = 0
    while i < len(text):
        ch = text[i]
        if quoted:
            if ch == '"':
                if i + 1 < len(text) and text[i + 1] == '"':
                    current.append('"')
                    i += 1
                else:
                    quoted = False
            else:
                current.append(ch)
        else:
            if ch == '"':
                quoted = True
            elif ch.isspace():
                if current:
                    values.append("".join(current))
                    current = []
            else:
                current.append(ch)
        i += 1
    if current:
        values.append("".join(current))
    return values


def _parse_record(text: str, comma_mode: bool) -> typing.List[str]:
    if not text.strip():
        return []
    if comma_mode:
        try:
            return next(csv.reader([text], delimiter=",", quotechar='"',
                                   doublequote=True, strict=False))
        except (csv.Error, StopIteration):
            return _parse_space_record(text)
    return _parse_space_record(text)


def _looks_like_date(value: str) -> bool:
    return bool(re.match(r"^\s*\d{1,4}[/-]\d{1,2}[/-]\d{1,4}\s*$", value or ""))


def _looks_like_data(row: typing.List[str]) -> bool:
    if not row:
        return False
    if _looks_like_date(row[0]):
        return True
    if len(row) > 1 and re.match(r"^\d{1,2}:\d{2}(?::\d{2})?$", row[1].strip()):
        return True
    return False


def _header_score(row: typing.List[str]) -> int:
    score = 0
    for value in row:
        low = value.strip().lower()
        if low in {"date", "time", "qty", "quantity", "productid",
                   "product id", "price", "url", "comments",
                   "description", "productdescription", "product type",
                   "producttype"}:
            score += 3
        elif re.search(r"[a-zA-Z]", value):
            score += 1
    return score


def parse_csv(raw_csv: str):
    if not isinstance(raw_csv, str) or not raw_csv:
        return {"columns": [], "rows": []}

    raw_csv = raw_csv.lstrip("\ufeff")
    physical_records = _split_logical_records(raw_csv)
    comma_mode = any(_has_unquoted_comma(record)
                     for record in physical_records if record.strip())

    parsed = []
    for record in physical_records:
        row = _parse_record(record, comma_mode)
        if row:
            parsed.append(row)

    if not parsed:
        return {"columns": [], "rows": []}

    first_data = None
    for index, row in enumerate(parsed):
        if _looks_like_data(row):
            first_data = index
            break

    if first_data is None:
        header_index = 0
        while header_index < len(parsed) and not parsed[header_index]:
            header_index += 1
        if header_index >= len(parsed):
            return {"columns": [], "rows": []}
        data_start = header_index + 1
    else:
        candidates = [
            i for i in range(first_data)
            if _header_score(parsed[i]) > 0
        ]
        if candidates:
            header_index = max(candidates, key=lambda i: (_header_score(parsed[i]), i))
        elif first_data > 0:
            header_index = first_data - 1
        else:
            header_index = 0
        data_start = first_data

    header_rows = [parsed[header_index]]
    base_width = len(parsed[header_index])

    backward = header_index - 1
    while backward >= 0:
        row = parsed[backward]
        if (_looks_like_data(row) or len(row) != base_width or
                _header_score(row) == 0):
            break
        header_rows.insert(0, row)
        backward -= 1

    forward = header_index + 1
    while forward < data_start:
        row = parsed[forward]
        if _looks_like_data(row) or len(row) != base_width:
            break
        header_rows.append(row)
        forward += 1

    if len(header_rows) == 1:
        columns = list(header_rows[0])
    else:
        columns = []
        for column_index in range(base_width):
            pieces = []
            for row in header_rows:
                if column_index < len(row):
                    value = row[column_index].strip()
                    if value and value not in pieces:
                        pieces.append(value)
            columns.append(" ".join(pieces))

    columns = [value.strip() for value in columns]
    for index, value in enumerate(columns):
        if not value:
            columns[index] = "column_{}".format(index + 1)

    rows = [list(row) for row in parsed[data_start:] if row]
    width = max([len(columns)] + [len(row) for row in rows])

    while len(columns) < width:
        columns.append("column_{}".format(len(columns) + 1))

    normalized = []
    for row in rows:
        if len(row) < width:
            row = row + [""] * (width - len(row))
        normalized.append(row[:width])

    return {"columns": columns, "rows": normalized}
